-- Minimal schema fixture for the task-lease renewal migration.
create table public.jarvis_agent_tasks (
    task_id text primary key,
    objective text not null default 'fixture objective',
    leader_id text not null default 'fixture-leader',
    assigned_agent_id text,
    attempt_id uuid,
    status text not null default 'ready',
    lease_expires_at timestamptz,
    updated_at timestamptz not null default now(),
    parent_task_id text,
    routine_id text
);
create table public.jarvis_agent_attempts (
    attempt_id uuid primary key,
    agent_id text not null,
    task_id text not null
);
create table public.jarvis_agent_events (
    event_id bigint generated by default as identity primary key,
    task_id text not null,
    attempt_id uuid not null,
    agent_id text not null,
    event_type text not null,
    payload jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now()
);

create table public.evolution_rewards (id bigint generated by default as identity primary key);
create table public.execution_plan_events (id bigint generated by default as identity primary key);
create table public.jarvis_agent_messages (id bigint generated by default as identity primary key);
create table public.jarvis_agents (id bigint generated by default as identity primary key);
create table public.jarvis_external_identities (id bigint generated by default as identity primary key);
create table public.jarvis_mobile_device_sessions (id bigint generated by default as identity primary key);
create table public.jarvis_mobile_push_devices (id bigint generated by default as identity primary key);
create table public.jarvis_mobile_push_events (id bigint generated by default as identity primary key);
create table public.jarvis_recovery_actions (id bigint generated by default as identity primary key);
create table public.jarvis_recovery_checkpoints (id bigint generated by default as identity primary key);
create table public.jarvis_recovery_events (id bigint generated by default as identity primary key);
create table public.jarvis_recovery_runs (id bigint generated by default as identity primary key);
create table public.jarvis_routine_definitions (id bigint generated by default as identity primary key);

alter table public.jarvis_agent_tasks enable row level security;
alter table public.jarvis_agent_attempts enable row level security;
alter table public.jarvis_agent_events enable row level security;
alter table public.evolution_rewards enable row level security;
alter table public.execution_plan_events enable row level security;
alter table public.jarvis_agent_messages enable row level security;
alter table public.jarvis_agents enable row level security;
alter table public.jarvis_external_identities enable row level security;
alter table public.jarvis_mobile_device_sessions enable row level security;
alter table public.jarvis_mobile_push_devices enable row level security;
alter table public.jarvis_mobile_push_events enable row level security;
alter table public.jarvis_recovery_actions enable row level security;
alter table public.jarvis_recovery_checkpoints enable row level security;
alter table public.jarvis_recovery_events enable row level security;
alter table public.jarvis_recovery_runs enable row level security;
alter table public.jarvis_routine_definitions enable row level security;
